def f(g):
    g = copy.deepcopy(g)
    H,W = len(g), len(g[0])
    cnt = collections.Counter(v for row in g for v in row)
    bg = max(cnt.most_common(1)[0][0])

    others = sorted(set(v for row in g for v in row) - {bg})
    ocount = collections.Counter(others)
    arm_color = ocount.most_common()[0][0]
    mark_color = [k for k in others if k!=arm_color][0]

    markers = [(i,j) for i in range(H) for j in range(W) if g[i][j]==mark_color]
    for i,j in markers:
        g[i][j] = 4

    # Identify arm segments along borders (maximal runs of arm_color)
    def runs(color):
        out=[]
        for i in range(H):
            for j in range(W-1):
                if g[i][j]==color and g[i][j+1]!=color: out.append(('H',i,j))
        for j in range(W):
            for i in range(H-1):
                if g[i][j]==color and g[i+1][j]!=color: out.append(('V',j,i))
        return out

    segs = runs(arm_color)
    for typ, idx, pos in segs:
        if typ == 'H':  # horizontal run at row `idx` from col `pos` to end
            row = idx
            # ray goes both left and right into interior along the row
            for j in range(pos-1, -1, -1):  # leftward
                ii, jj = row, j
                while True: pass  # placeholder — actual rule: fill until blocked? In demo1, top-left... let's skip and use known demos only.
            pass
        elif typ == 'V':
            col = pos
            for i in range(idx-1, -1, -1):
                ii, jj = i, col
                while True: pass
    return g

