def f_stop_at_marker(g):
    import copy
    g = copy.deepcopy(g); H,W=len(g),len(g[0])
    cnt=collections.Counter(v for row in g for v in row); bg=max(cnt.most_common(1)[0][0])
    others=set(v for row in g for v in row)-{bg}; ocnt=collections.Counter(others)
    arm=ocnt.most_common()[0][0]; mark=[k for k in others if k!=arm][0]
    # convert markers to 4
    for i in range(H):
        for j in range(W):
            if g[i][j]==mark: g[i][j]=4
    # arm segments on borders: maximal runs of arm color
    def segs(color):
        out=[]
        for i in range(H):
            for j in range(W-1):
                if g[i][j]==color and g[i][j+1]!=color: out.append(('H',i,j))
        for j in range(W):
            for i in range(H-1):
                if g[i][j]==color and g[i+1][j]!=color: out.append(('V',j,i))
        return out
    for typ,idx,pos in segs(arm):
        if typ=='H':
            # horizontal run at row idx, col pos..W-1; ray goes left into grid
            for j in range(pos-1, -1, -1):
                g[idx][j]=mark
            # also rightward from the other end of run to W-1? (both directions of line)
            # In demo4, left-arm ran rows3-11 and filled to the right fully until marker → yes both directions
            for j in range(pos+1, W):
                g[idx][j]=mark
        elif typ=='V':
            for i in range(idx-1, -1, -1):
                g[i][pos]=mark
            for i in range(idx+1, H):
                g[i][pos]=mark
    return g

